import { readFileSync } from "node:fs";

const pkg = JSON.parse(
  readFileSync(new URL("../package.json", import.meta.url), "utf8"),
);

if (process.argv[2] === "version") {
  process.stdout.write(pkg.version + "\n");
} else {
  process.stderr.write("error: unknown or missing command\n");
  process.exitCode = 1;
}

import test from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const cli = fileURLToPath(new URL("../src/cli.js", import.meta.url));
const pkg = JSON.parse(
  readFileSync(new URL("../package.json", import.meta.url), "utf8"),
);

test("version prints package version", () => {
  const r = spawnSync(process.execPath, [cli, "version"], { encoding: "utf8" });
  assert.equal(r.status, 0);
  assert.equal(r.stdout, pkg.version + "\n");
});

test("unknown command exits 1 with stderr", () => {
  const r = spawnSync(process.execPath, [cli, "bogus"], { encoding: "utf8" });
  assert.equal(r.status, 1);
  assert.notEqual(r.stderr.trim(), "");
});

test("no command exits 1 with stderr", () => {
  const r = spawnSync(process.execPath, [cli], { encoding: "utf8" });
  assert.equal(r.status, 1);
  assert.notEqual(r.stderr.trim(), "");
});

